-- Seed the finance_ops annotation tables from the 2026-07-25 tracker export.
-- Run AFTER sql/finance_ops.sql, once. Safe to re-run: each section clears the
-- rows it is about to insert, so a second run does not create duplicates.
--
-- Why this matters: sla_po_emission holds the date a PO was FIRST seen, which is
-- what the payout SLA deadline is measured from. Without it the app falls back to
-- BigQuery's purchase_order_updated_at (a bulk-sync timestamp), and every payout
-- looks freshly due instead of breached.

-- 1. PO first-emission dates ------------------------------------------------
DELETE FROM `naboo-app-365515.finance_ops.sla_po_emission` WHERE TRUE;

-- 2. Partner outreach statuses ----------------------------------------------
DELETE FROM `naboo-app-365515.finance_ops.sla_partner_status` WHERE TRUE;

-- 3. Comments ---------------------------------------------------------------
DELETE FROM `naboo-app-365515.finance_ops.sla_event_comments` WHERE user_id = 'legacy-import';
